# ---------------- 直答替换 ----------------
old_answers = {
    "燃烧": "纸遇到火点着",
    "溶解": "糖放进水里搅一搅不见了——溶解了；盐放进菜里也会溶解，菜就变咸了",
    "汽水气泡": "打开汽水压强减小，二氧化碳溶解度降低跑出来",
    "血液循环": "心脏跳动推动血液流遍全身",
}
new_answers = {
    "燃烧": BURN_ANSWER, "溶解": DISSOLVE_ANSWER,
    "汽水气泡": SODA_ANSWER, "血液循环": CIRCULATE_ANSWER,
}
for key, old in old_answers.items():
    m = re.search(r'    "%s": "%s",' % (key, old), src)
    assert m, key
    src = src[:m.start()] + '    "%s": "%s",' % (key, new_answers[key]) + src[m.end():]

# ---------------- 触发词扩充 ----------------
UPD = {
    "燃烧": ['着火了', '烧起来', '点燃', '燃烧', '着火点', '灭火', '为什么着火', '自燃', '火烧', '为什么烧起来', '怎么灭火', '燃点'],
    "溶解": ['糖化了', '盐化了', '变咸', '咸了', '放盐', '糖放水里不见了', '溶解', '溶解了', '化在水里', '溶于', '溶解速度', '怎么溶解'],
    "汽水气泡": ['汽水气泡', '汽水为什么冒泡', '打开汽水', '冒泡', '气泡', '没气了', '打嗝', '喷出来', '摇晃汽水', '二氧化碳'],
    "血液循环": ['心跳', '血管', '血液循环', '心跳加速', '心跳快', '为什么心跳', '血液', '心脏', '供血', '泵血'],
}
for theme, lst in UPD.items():
    m = re.search(r'"%s":\s*\[[^\]]*\]' % theme, src)
    assert m, theme
    new = '"%s": [%s]' % (theme, ", ".join('"%s"' % t for t in lst))
    src = src[:m.start()] + new + src[m.end():]

open(TRANSLATE_PY, "w", encoding="utf-8").write(src)
py_compile.compile(TRANSLATE_PY, doraise=True)
print("round14 patch OK:", {k: len(v) for k, v in UPD.items()})
